import numpy as np
t=df['t'].values; P=df['P'].values; y=df['dP_dt'].values
def run(pows,tp,extra=[]):
    cols=[t**j*P**k for j in tp for k in pows]+extra
    X=np.column_stack(cols); c=np.linalg.lstsq(X,y,rcond=None)[0]; r=y-X@c
    return np.var(r)/np.var(y), c
for pows in [[0,1,2,3],[0,0.5,1,1.5,2],[0,0.5,1,1.5,2,2.5,3],[-1,0,1,2,3],[0,1,2,3,4,-1]]:
